create extension if not exists pgcrypto;
create type public.case_role as enum ('owner','investor','contractor','surveyor','housing_provider','council_officer','admin');
create type public.review_status as enum ('draft','reviewed','rejected','retired');
create table public.organisations(id uuid primary key default gen_random_uuid(),name text not null,type text not null,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,created_at timestamptz not null default now());
create table public.organisation_members(org_id uuid references public.organisations on delete cascade,user_id uuid references auth.users on delete cascade,role public.case_role not null,primary key(org_id,user_id));
create table public.properties(id uuid primary key default gen_random_uuid(),created_by uuid not null references auth.users,postcode text not null,address_line text,empty_since date,owner_type text,intended_use text,status text not null default 'intake',created_at timestamptz not null default now());
create table public.cases(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties on delete cascade,owner_org_id uuid references public.organisations,status text not null default 'assessment',created_at timestamptz not null default now());
create table public.source_records(id uuid primary key default gen_random_uuid(),source_system text not null,source_url text not null,source_hash text,last_checked_at timestamptz,confidence numeric check(confidence between 0 and 1),raw jsonb not null default '{}'::jsonb,unique(source_system,source_url));
create table public.funding_schemes(id uuid primary key default gen_random_uuid(),authority text not null,name text not null,scheme_type text,max_amount numeric,min_empty_months int,eligible_owner_types text[] not null default '{}',eligible_uses text[] not null default '{}',eligible_works text[] not null default '{}',geography jsonb not null default '{}'::jsonb,source_id uuid not null references public.source_records,status public.review_status not null default 'draft',reviewed_by uuid references auth.users,reviewed_at timestamptz,valid_from date,valid_to date,created_at timestamptz not null default now());
create table public.funding_matches(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cases on delete cascade,scheme_id uuid not null references public.funding_schemes,eligible boolean,confidence numeric,explanation jsonb,created_at timestamptz not null default now(),unique(case_id,scheme_id));
create table public.assessments(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cases on delete cascade,type text not null,result jsonb not null,confidence numeric,requires_human_review boolean not null default true,created_at timestamptz not null default now());
create table public.evidence_items(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cases on delete cascade,external_dokuvera_id text,kind text not null,file_name text,sha256 text,captured_at timestamptz,latitude numeric,longitude numeric,verified boolean not null default false,metadata jsonb not null default '{}'::jsonb);
create table public.quote_requests(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cases on delete cascade,work_scope jsonb not null,status text not null default 'draft',created_at timestamptz not null default now());
create table public.quotes(id uuid primary key default gen_random_uuid(),quote_request_id uuid references public.quote_requests on delete cascade,contractor_org_id uuid references public.organisations,external_craftvaro_id text,amount numeric,status text not null default 'submitted',details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),case_id uuid not null unique references public.cases on delete cascade,contractor_org_id uuid references public.organisations,status text not null default 'planned',budget numeric,start_date date,target_completion date,created_at timestamptz not null default now());
create table public.project_milestones(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects on delete cascade,name text not null,status text not null default 'pending',due_at timestamptz,evidence_required text[] not null default '{}',completed_at timestamptz);
create table public.agent_runs(id uuid primary key default gen_random_uuid(),case_id uuid references public.cases on delete cascade,agent text not null,input jsonb not null,output jsonb not null,confidence numeric,requires_human_review boolean not null default false,model_version text,sources uuid[] not null default '{}',created_at timestamptz not null default now());
create table public.learning_outcomes(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cases on delete cascade,event text not null,features jsonb not null,target numeric,occurred_at timestamptz not null default now());
create table public.audit_log(id bigint generated always as identity primary key,actor_id uuid,entity_type text not null,entity_id uuid,action text not null,before jsonb,after jsonb,created_at timestamptz not null default now());

grant select, insert, update, delete on public.organisations, public.profiles, public.organisation_members, public.properties, public.cases, public.source_records, public.funding_schemes, public.funding_matches, public.assessments, public.evidence_items, public.quote_requests, public.quotes, public.projects, public.project_milestones, public.agent_runs, public.learning_outcomes, public.audit_log to authenticated;
grant all on public.organisations, public.profiles, public.organisation_members, public.properties, public.cases, public.source_records, public.funding_schemes, public.funding_matches, public.assessments, public.evidence_items, public.quote_requests, public.quotes, public.projects, public.project_milestones, public.agent_runs, public.learning_outcomes, public.audit_log to service_role;
grant usage, select on sequence public.audit_log_id_seq to authenticated, service_role;

alter table public.properties enable row level security; alter table public.cases enable row level security; alter table public.funding_matches enable row level security; alter table public.assessments enable row level security; alter table public.evidence_items enable row level security; alter table public.quote_requests enable row level security; alter table public.projects enable row level security;
create policy "property creator read" on public.properties for select using(created_by=auth.uid());
create policy "property creator insert" on public.properties for insert with check(created_by=auth.uid());
create policy "case owner read" on public.cases for select using(exists(select 1 from public.properties p where p.id=property_id and p.created_by=auth.uid()));
create policy "matches via case" on public.funding_matches for select using(exists(select 1 from public.cases c join public.properties p on p.id=c.property_id where c.id=case_id and p.created_by=auth.uid()));